function unwrap<T>(settled: PromiseSettledResult<T>): T {
    if (settled.status === "rejected") {
        // Rethrow the step's original error — DBOS already logged which
        // step failed, and downstream debugging wants the real cause.
        throw settled.reason;
    }
    return settled.value;
}

/** The list a fan_out node dispatches over.
 *
 * A bare `.map()` on a missing key fails with "Cannot read properties
 * of undefined (reading 'map')", which names neither the node nor the
 * reference — in generated code that is close to undebuggable, and the
 * cause is almost always an upstream node that didn't return the key
 * the IR says it does. One call turns that into an actionable message.
 * Found by running it: the first live fan_out run hit exactly this. */
function fanOutList(value: unknown, nodeId: string, ref: string): unknown[] {
    if (!Array.isArray(value)) {
        const got = value === null ? "null" : typeof value;
        throw new Error(
            `fan_out node '${nodeId}' expected an array from '${ref}', got ${got}. ` +
                `The upstream node must return that key as a list.`,
        );
    }
    return value;
}

/** Why `pipelineInput` cannot start a run, or null when it can.
 *
 * An omitted optional field reads as undefined, which is what the input
 * schema allows. A missing required field would read as undefined too and
 * surface much later as some unrelated error, so the run checks those
 * first and fails naming them. A run started with no payload at all is
 * reported the same way. The Python runtimes emit the same check
 * (`_missing_inputs_error`), so a bad input reports identically on every
 * target. */
function missingInputsError(pipelineInput: unknown, required: string[]): string | null {
    if (pipelineInput === null || Array.isArray(pipelineInput)) {
        const got = pipelineInput === null ? "null" : "array";
        return `pipeline input must be a JSON object, got ${got}`;
    }
    if (typeof pipelineInput !== "object") {
        return `pipeline input must be a JSON object, got ${typeof pipelineInput}`;
    }
    const missing = required.filter(
        (name) => !Object.prototype.hasOwnProperty.call(pipelineInput, name),
    );
    return missing.length > 0
        ? `pipeline input is missing required field(s): ${missing.join(", ")}`
        : null;
}

/** A gate's message: each `{name}` filled from `values`, its bound inputs.
 *
 * A string is used as is; any other value is written as JSON.stringify
 * writes it, which the Python runtimes reproduce (`_render_gate_message`),
 * so one run reads the same on every runtime. A placeholder whose value the
 * run does not have (`roteGateField`) is kept as written. Then every
 * invisible character (controls, format characters such as bidi overrides,
 * line and paragraph separators, lone surrogates) is spelled `\uXXXX`, so a
 * value cannot drive the terminal the message is shown on. The newline and
 * the tab stay. */
const ROTE_GATE_PLACEHOLDER = new RegExp("\\{([A-Za-z_][A-Za-z0-9_]*)\\}", "g");
const ROTE_GATE_INVISIBLE = /^[\p{Cc}\p{Cf}\p{Zl}\p{Zp}\p{Cs}]$/u;

/** `source[field]`, or undefined when the run does not have that value (an
 * omitted optional input, a key an upstream result lacks), so its
 * placeholder is kept as written. The Python twin is `_gate_input`. */
function roteGateField(source: unknown, field: string): unknown {
    return source !== null &&
        typeof source === "object" &&
        !Array.isArray(source) &&
        Object.prototype.hasOwnProperty.call(source, field)
        ? (source as Record<string, unknown>)[field]
        : undefined;
}

function renderGateMessage(template: string, values: Record<string, unknown>): string {
    const filled = template.replace(ROTE_GATE_PLACEHOLDER, (whole: string, name: string) => {
        const value = Object.prototype.hasOwnProperty.call(values, name) ? values[name] : undefined;
        if (value === undefined) return whole;
        return typeof value === "string" ? value : String(JSON.stringify(value));
    });
    let out = "";
    for (const ch of filled) {
        if (ch !== "\n" && ch !== "\t" && ROTE_GATE_INVISIBLE.test(ch)) {
            const code = ch.codePointAt(0) as number;
            out +=
                code <= 0xffff
                    ? `\\u${code.toString(16).padStart(4, "0")}`
                    : `\\U${code.toString(16).padStart(8, "0")}`;
        } else {
            out += ch;
        }
    }
    return out;
}

/** The input type an impl declares, so a call can be checked against it.
 *
 * The implement skill says to replace a stub's `unknown` input with a real
 * interface. Upstream values are `unknown` here (the pipeline input, a
 * fanned element), so each one is asserted to the field type the impl
 * declares: a key the impl does not declare, or a declared key the IR does
 * not send, still fails tsc. A stub's `unknown` input reads as an open
 * record, so the scaffold compiles too. */
type ImplInput<F> = F extends (input: infer I, ...rest: never[]) => unknown
    ? unknown extends I
        ? Record<string, unknown>
        : I
    : never;

/**
 * End-to-end BDR outreach campaign workflow for pharma/biotech research
 */
export const runPipeline = DBOS.registerWorkflow(
    async (pipelineInput: Record<string, unknown>): Promise<Record<string, unknown>> => {
        const inputError = missingInputsError(pipelineInput, ["campaign_type", "condition_acronym", "condition_full", "drug_brand", "drug_generic", "manufacturer", "target_quota", "therapeutic_area"]);
        if (inputError !== null) {
            throw new Error(inputError);
        }        // Every gate this run has reached, for the rote_gate_status event.
        const roteGates: Record<string, unknown>[] = [];

        // ─── Wave 1 ───
        // Parallel fan-out: run every step in the wave concurrently
        // and settle them all — Promise.allSettled per the DBOS docs
        // (a bare Promise.all can crash the Node process on unhandled
        // rejections).
        const [target_research_settled, taxonomy_lookup_settled] = await Promise.allSettled([
            targetResearchStep({
                brief: pipelineInput,
            }),
            taxonomyLookupStep({
                brief: pipelineInput as ImplInput<typeof taxonomyLookup>["brief"],
            }),
        ]);
        const target_research_result = unwrap(target_research_settled);
        const taxonomy_lookup_result = unwrap(taxonomy_lookup_settled);

        // ─── Wave 2 ───
        const lead_generation_loop_result = await leadGenerationLoopStep(
            {
                brief: pipelineInput,
                intel: target_research_result,
                taxonomy: taxonomy_lookup_result,
                target_quota: pipelineInput["target_quota"],
            },
        );

        // ─── Wave 3 ───
        // ─── HITL gate: contact_review_gate ───
        // Durable receive: the workflow parks in the system database until
        // DBOS.send(workflowID, payload, "contact_review_approved")
        // delivers the resume message. Survives process restarts. The
        // timeout is explicit — DBOS.recv defaults to 60s when omitted.
        // First it says which gate the run waits at, and the gate's
        // message, in the workflow event `rote run` watches (portable, so
        // the Python DBOSClient can read it). Display only: nothing is
        // sent to a person or a channel.
        roteGates.push({ gate: "contact_review_gate", signal: "contact_review_approved", message: renderGateMessage("BDR campaign awaiting review: {drug_brand} for {condition_acronym}.\nApprove, remove or reprioritize the vetted contacts before CRM upload.\n", { "drug_brand": roteGateField(pipelineInput, "drug_brand"), "condition_acronym": roteGateField(pipelineInput, "condition_acronym") }) });
        await DBOS.setEvent(
            "rote_gate_status",
            { reached: [...roteGates] },
            { serializationType: "portable" },
        );
        const contact_review_gate_result = await DBOS.recv<Record<string, unknown>>(
            "contact_review_approved",
            604800, // 7d
        );
        if (contact_review_gate_result === null) {
            throw new Error(
                "HITL gate 'contact_review_gate' timed out after 7d waiting " +
                    "for signal 'contact_review_approved'",
            );
        }

        // ─── Wave 4 ───
        const hubspot_upsert_result = await hubspotUpsertStep(
            {
                contacts: contact_review_gate_result["approved_contacts"] as ImplInput<typeof hubspotUpsert>["contacts"],
                batch_size: 100,
            },
        );

        // ─── Wave 5 ───
        const hubspot_create_list_result = await hubspotCreateListStep(
            {
                campaign_name: pipelineInput["drug_brand"] as ImplInput<typeof hubspotCreateList>["campaign_name"],
                contacts: hubspot_upsert_result["upserted"] as ImplInput<typeof hubspotCreateList>["contacts"],
                add_batch_size: 250,
            },
        );

        // ─── Wave 6 ───
        const exclusion_check_dnc_result = await exclusionCheckDncStep(
            {
                contacts: hubspot_upsert_result["upserted"] as ImplInput<typeof exclusionCheckDnc>["contacts"],
            },
        );

        // ─── Wave 7 ───
        const exclusion_check_recent_result = await exclusionCheckRecentStep(
            {
                contacts: exclusion_check_dnc_result["passed"] as ImplInput<typeof exclusionCheckRecent>["contacts"],
                days_back: 30,
                direction: "OUTBOUND",
            },
        );

        // ─── Wave 8 ───
        const exclusion_check_sequence_result = await exclusionCheckSequenceStep(
            {
                contacts: exclusion_check_recent_result["passed"] as ImplInput<typeof exclusionCheckSequence>["contacts"],
            },
        );

        // ─── Wave 9 ───
        // fan_out: personalize_email runs once per element of the bound list,
        // each as its own durable step.
        const personalize_email_settled = await Promise.allSettled(
            fanOutList(
                exclusion_check_sequence_result["passed"],
                "personalize_email",
                "exclusion_check_sequence.output.passed",
            ).map((_item) => personalizeEmailStep({ contact: _item, intel: target_research_result, campaign_type: pipelineInput["campaign_type"] })),
        );
        const personalize_email_result = personalize_email_settled.map(unwrap);

        // ─── Wave 10 ───
        const create_sales_template_result = await createSalesTemplateStep(
            {
                campaign_name: pipelineInput["drug_brand"] as ImplInput<typeof createSalesTemplate>["campaign_name"],
                personalizations: personalize_email_result as ImplInput<typeof createSalesTemplate>["personalizations"],
            },
        );

        // ─── Wave 11 ───
        const pre_enrollment_report_result = await preEnrollmentReportStep(
            {
                campaign_name: pipelineInput["drug_brand"] as ImplInput<typeof preEnrollmentReport>["campaign_name"],
                passed_contacts: exclusion_check_sequence_result["passed"] as ImplInput<typeof preEnrollmentReport>["passed_contacts"],
                exclusions: exclusion_check_sequence_result["excluded"] as ImplInput<typeof preEnrollmentReport>["exclusions"],
                template_ids: create_sales_template_result["template_ids"] as ImplInput<typeof preEnrollmentReport>["template_ids"],
            },
        );

        // ─── Wave 12 ───
        // ─── HITL gate: manual_enrollment_handoff ───
        // Durable receive: the workflow parks in the system database until
        // DBOS.send(workflowID, payload, "bdr_enrollment_complete")
        // delivers the resume message. Survives process restarts. The
        // timeout is explicit — DBOS.recv defaults to 60s when omitted.
        // First it says which gate the run waits at, and the gate's
        // message, in the workflow event `rote run` watches (portable, so
        // the Python DBOSClient can read it). Display only: nothing is
        // sent to a person or a channel.
        roteGates.push({ gate: "manual_enrollment_handoff", signal: "bdr_enrollment_complete", message: renderGateMessage("BDR campaign ready for manual enrollment: {campaign_name}\n\n{report_markdown}\n", { "campaign_name": roteGateField(pipelineInput, "drug_brand"), "report_markdown": roteGateField(pre_enrollment_report_result, "report_markdown") }) });
        await DBOS.setEvent(
            "rote_gate_status",
            { reached: [...roteGates] },
            { serializationType: "portable" },
        );
        const manual_enrollment_handoff_result = await DBOS.recv<Record<string, unknown>>(
            "bdr_enrollment_complete",
            1209600, // 14d
        );
        if (manual_enrollment_handoff_result === null) {
            throw new Error(
                "HITL gate 'manual_enrollment_handoff' timed out after 14d waiting " +
                    "for signal 'bdr_enrollment_complete'",
            );
        }

        return {
            "manual_enrollment_handoff": manual_enrollment_handoff_result,
        };
    },
    { name: "BdrCampaign_26abf258" },
);

// ───────── Entrypoint ─────────

export async function main(): Promise<void> {
    DBOS.setConfig({
        name: "bdr-campaign",
        // undefined → the SDK default
        // (postgresql://postgres:dbos@localhost:5432/<name>_dbos_sys),
        // which matches `npx dbos postgres start`. The TS SDK is
        // Postgres-only — unlike DBOS Python there is no SQLite mode.
        systemDatabaseUrl: process.env.DBOS_SYSTEM_DATABASE_URL,
    });
    // launch() inside the try: a launch that fails part way (a
    // Postgres still restarting after its init phase) leaves pools
    // and timers alive, so without the shutdown below the process
    // never exits and the error is never seen.
    try {
        await DBOS.launch();
        const pipelineInput = JSON.parse(
            process.argv[2] ?? "{}",
        ) as Record<string, unknown>;
        const handle = await DBOS.startWorkflow(runPipeline)(pipelineInput);
        console.error(`workflow started: ${handle.workflowID}`);
        console.log(JSON.stringify(await handle.getResult(), null, 2));
    } finally {
        await DBOS.shutdown();
    }
}

if (require.main === module) {
    main().catch((err) => {
        if (isRoteMcpConfigError(err)) {
            console.error(`error: ${err instanceof Error ? err.message : String(err)}`);
            process.exitCode = 2;
            return;
        }
        console.error(err);
        process.exitCode = 1;
    });
}
